@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700;800&family=Open+Sans:wght@400;600&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Ottimizzazioni scroll globali per eliminare lag */
* {
  -webkit-overflow-scrolling: touch;
  scroll-behavior: smooth;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}

body {
  overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

/* Ottimizzazioni per elementi con transizioni */
.navbar-transition,
.smooth-scroll {
  transform: translateZ(0);
  backface-visibility: hidden;
  perspective: 1000px;
  will-change: transform, background-color, backdrop-filter, padding;
  transition: all 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
}

/* Transizione specifica per la navbar quando cambia dimensione */
.navbar-transition {
  transition: all 0.4s cubic-bezier(0.25, 0.1, 0.25, 1) !important;
}

.logo-transparent {
  object-fit: contain;
  mix-blend-mode: multiply;
  filter: brightness(1.1) contrast(1.1) drop-shadow(0 0 0 transparent);
  background-color: transparent !important;
  background: none !important;
  -webkit-background-clip: content-box;
  background-clip: content-box;
  isolation: isolate;
}

:root {
  --background: 0 0% 100%;
  --foreground: 0 0% 13%;
  --muted: 240 4.8% 95.9%;
  --muted-foreground: 25 5.3% 44.7%;
  --popover: 0 0% 100%;
  --popover-foreground: 0 0% 13%;
  --card: 0 0% 100%;
  --card-foreground: 0 0% 13%;
