  }
}

/* Ottimizzazioni per tabelle nutrizionali su mobile */
.nutrition-table-mobile {
  @apply text-xs;
}

.nutrition-table-mobile th,
.nutrition-table-mobile td {
  @apply px-2 py-1;
}

/* Responsive per ingredienti lunghi */
.ingredients-text {
  @apply break-words hyphens-auto;
}

