import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

client/src/hooks/use-toast.ts.content:
import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

client/src/hooks/useAuth.ts.content:
import { useState, useEffect } from 'react';

export interface AuthUser {
  username: string;
  loginTime?: string;
}

export interface AuthState {
  isAuthenticated: boolean;
  user: AuthUser | null;
  isLoading: boolean;
  error: string | null;
}

export const useAuth = () => {
  const [authState, setAuthState] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
    isLoading: true,
    error: null
  });

  const checkAuthStatus = async () => {
    try {
      setAuthState(prev => ({ ...prev, isLoading: true, error: null }));

      const response = await fetch('/api/auth/check', {
        method: 'GET',
        credentials: 'include'
      });

      if (!response.ok) {
        throw new Error('Failed to check auth status');
      }

      const data = await response.json();

      if (data.success) {
        setAuthState({
          isAuthenticated: data.authenticated,
          user: data.user || null,
          isLoading: false,
          error: null
        });
      } else {
        setAuthState({
          isAuthenticated: false,
          user: null,
          isLoading: false,
          error: data.message || 'Auth check failed'
        });
      }
    } catch (error) {
      console.error('Error checking auth status:', error);
      setAuthState({
        isAuthenticated: false,
        user: null,
        isLoading: false,
        error: error instanceof Error ? error.message : 'Auth check failed'
      });
    }
  };

  const login = async (username: string, password: string): Promise<{ success: boolean; message?: string }> => {
    try {
      setAuthState(prev => ({ ...prev, isLoading: true, error: null }));

      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({ username, password }),
      });

      const data = await response.json();

      if (data.success) {
        // Update immediato e sincrono dello stato
        setAuthState({
          isAuthenticated: true,
          user: data.user,
          isLoading: false,
          error: null
        });
        return { success: true };
      } else {
        setAuthState(prev => ({
          ...prev,
          isLoading: false,
          error: data.message || 'Login failed'
        }));
        return { success: false, message: data.message || 'Login failed' };
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Login failed';
      setAuthState(prev => ({
        ...prev,
        isLoading: false,
        error: errorMessage
      }));
      return { success: false, message: errorMessage };
    }
  };

  const logout = async (): Promise<{ success: boolean; message?: string }> => {
    try {
      setAuthState(prev => ({ ...prev, isLoading: true }));

      const response = await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include'
      });

      const data = await response.json();

      // Sempre resetta lo stato locale anche se la richiesta fallisce
      setAuthState({
        isAuthenticated: false,
        user: null,
        isLoading: false,
        error: null
      });

      return { success: data.success || true, message: data.message };
    } catch (error) {
      // Anche in caso di errore, resetta lo stato locale
      setAuthState({
        isAuthenticated: false,
        user: null,
        isLoading: false,
        error: null
      });
      return { success: true, message: 'Logout completed locally' };
    }
  };

  // Check auth status on mount
  useEffect(() => {
    checkAuthStatus();
  }, []);

  return {
    ...authState,
    login,
    logout,
    checkAuthStatus
  };
};

client/src/hooks/useFavorites.ts.content:
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

interface Favorite {
  id: number;
  userId: number;
  productId: number;
  createdAt: string;
}

interface FavoritesResponse {
  favorites: Favorite[];
}

interface FavoriteStatusResponse {
  success: boolean;
  isFavorite: boolean;
}

interface UseFavoritesProps {
  userId?: number;
}

export function useFavorites({ userId }: UseFavoritesProps = {}) {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Get user favorites
  const { data: favorites, isLoading: isLoadingFavorites } = useQuery<FavoritesResponse>({
    queryKey: [`/api/favorites/${userId}`],
    enabled: !!userId,
    staleTime: 1000 * 60 * 5, // 5 minutes
  });

  // Add to favorites mutation
  const addToFavoritesMutation = useMutation({
    mutationFn: async ({ productId }: { productId: number }) => {
      if (!userId) {
        throw new Error("User must be logged in to add favorites");
      }
      return await apiRequest("POST", "/api/favorites", { userId, productId });
    },
    onSuccess: (data, { productId }) => {
      // Invalidate favorites list
      queryClient.invalidateQueries({ queryKey: [`/api/favorites/${userId}`] });

      // Update individual favorite status cache
      queryClient.setQueryData([`/api/favorites/${userId}/${productId}`], {
        success: true,
        isFavorite: true,
      });

      toast({
        title: "Aggiunto ai preferiti ✨",
        description: "Il prodotto è stato aggiunto ai tuoi preferiti",
        duration: 3000,
      });
    },
    onError: (error: any) => {
      const message = error?.message || "Errore durante l'aggiunta ai preferiti";
      toast({
        title: "Errore",
        description: message,
        variant: "destructive",
        duration: 4000,
      });
    },
  });

  // Remove from favorites mutation
  const removeFromFavoritesMutation = useMutation({
    mutationFn: async ({ productId }: { productId: number }) => {
      if (!userId) {
        throw new Error("User must be logged in to remove favorites");
      }
      return await apiRequest("DELETE", "/api/favorites", { userId, productId });
    },
    onSuccess: (data, { productId }) => {
      // Invalidate favorites list
      queryClient.invalidateQueries({ queryKey: [`/api/favorites/${userId}`] });

      // Update individual favorite status cache
      queryClient.setQueryData([`/api/favorites/${userId}/${productId}`], {
        success: true,
        isFavorite: false,
      });

      toast({
        title: "Rimosso dai preferiti",
        description: "Il prodotto è stato rimosso dai tuoi preferiti",
        duration: 3000,
      });
    },
    onError: (error: any) => {
      const message = error?.message || "Errore durante la rimozione dai preferiti";
      toast({
        title: "Errore",
        description: message,
        variant: "destructive",
        duration: 4000,
      });
    },
  });

  // Clear all favorites mutation
  const clearAllFavoritesMutation = useMutation({
    mutationFn: async () => {
      if (!userId) {
        throw new Error("User must be logged in to clear favorites");
      }
      return await apiRequest("DELETE", `/api/favorites/${userId}`);
    },
    onSuccess: () => {
      // Invalidate all favorites-related queries
      queryClient.invalidateQueries({ queryKey: [`/api/favorites/${userId}`] });

      toast({
        title: "Preferiti cancellati",
        description: "Tutti i preferiti sono stati rimossi con successo",
        duration: 3000,
      });
    },
    onError: (error: any) => {
      const message = error?.message || "Errore durante la cancellazione dei preferiti";
      toast({
        title: "Errore",
        description: message,
        variant: "destructive",
        duration: 4000,
      });
    },
  });

  // Check if product is favorite
  const useIsFavorite = (productId?: number) => {
    return useQuery<FavoriteStatusResponse>({
      queryKey: [`/api/favorites/${userId}/${productId}`],
      enabled: !!userId && !!productId,
      staleTime: 1000 * 60 * 5, // 5 minutes
    });
  };

  // Toggle favorite status
  const toggleFavorite = async (productId: number) => {
    if (!userId) {
      toast({
        title: "Accesso richiesto",
        description: "Devi essere loggato per gestire i preferiti",
        variant: "destructive",
        duration: 4000,
      });
      return;
    }

    try {
      // Check current status
      const currentStatus = await queryClient.fetchQuery<FavoriteStatusResponse>({
        queryKey: [`/api/favorites/${userId}/${productId}`],
      });

      if (currentStatus?.isFavorite) {
        await removeFromFavoritesMutation.mutateAsync({ productId });
      } else {
        await addToFavoritesMutation.mutateAsync({ productId });
      }
    } catch (error) {
      console.error("Error toggling favorite:", error);
    }
  };

  return {
    favorites: favorites?.favorites || [],
    isLoadingFavorites,
    addToFavorites: addToFavoritesMutation.mutateAsync,
    removeFromFavorites: removeFromFavoritesMutation.mutateAsync,
    clearAllFavorites: clearAllFavoritesMutation.mutateAsync,
    toggleFavorite,
    useIsFavorite,
    isAddingToFavorites: addToFavoritesMutation.isPending,
    isRemovingFromFavorites: removeFromFavoritesMutation.isPending,
    isClearingFavorites: clearAllFavoritesMutation.isPending,
  };
}

