            {lines.find((line: string) => line.toLowerCase().includes('vnr:')) && (
              <div className="text-sm text-gray-600 mt-4 p-3 bg-gray-50 rounded">
                <p>{lines.find((line: string) => line.toLowerCase().includes('vnr:'))}</p>
              </div>
            )}
