                    }

                    return null;
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Sezione Profilo Aminoacidico */}
        {sections.aminoacidi && (
          <div className="bg-white rounded-lg shadow-sm border">
            <div className="bg-gradient-to-r from-green-100 to-emerald-200 px-4 py-3 rounded-t-lg">
