import { useParams } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Link } from "wouter";
import { ArrowLeft } from "lucide-react";

interface ProductVariant {
  id: number;
  slug: string;
  name: string;
  flavor: string | null;
  quantity: string | null;
  description: string;
}

interface GroupedProduct {
  id: number;
  slug: string;
  name: string;
  brand_name: string;
  category_name: string;
  description: string;
  variant_count: number;
  variants: ProductVariant[];
}

export default function ProductVariants() {
  const { category } = useParams();

  const { data: groupedProducts, isLoading } = useQuery({
    queryKey: ['/api/products-grouped', category],
    queryFn: async () => {
      const response = await fetch(`/api/products-grouped/${category}`);
      if (!response.ok) throw new Error('Failed to fetch grouped products');
      return response.json() as GroupedProduct[];
    },
  });

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-yellow-50 to-orange-50 p-6">
        <div className="container mx-auto">
          <div className="animate-pulse space-y-4">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="h-32 bg-gray-200 rounded-lg"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  const categoryName = category?.charAt(0).toUpperCase() + category?.slice(1).replace('-', ' ') || '';

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-50 to-orange-50">
      <div className="container mx-auto py-8 px-4">
        <div className="mb-8">
          <Link href={`/products/${category}`}>
            <Button variant="ghost" className="mb-4">
              <ArrowLeft className="mr-2 h-4 w-4" />
              Torna alla lista prodotti
            </Button>
          </Link>
          <h1 className="text-4xl font-bold text-gray-900 mb-2">
            {categoryName} - Varianti Raggruppate
          </h1>
          <p className="text-lg text-gray-600">
            Prodotti organizzati per gruppo con tutte le varianti disponibili
          </p>
        </div>

        <div className="grid gap-6">
          {groupedProducts?.map((group) => (
            <Card key={group.id} className="shadow-lg hover:shadow-xl transition-shadow">
              <CardHeader>
                <div className="flex justify-between items-start">
                  <div>
                    <CardTitle className="text-2xl text-gray-900">
                      {group.name}
                    </CardTitle>
                    <CardDescription className="text-lg">
                      <Badge variant="secondary" className="mr-2">{group.brand_name}</Badge>
                      {group.description}
                    </CardDescription>
                  </div>
                  <Badge variant="outline" className="text-sm">
                    {group.variant_count} varianti
                  </Badge>
                </div>
              </CardHeader>

              <CardContent>
                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {JSON.parse(group.variants).map((variant: ProductVariant) => (
                    <div key={variant.id} className="border rounded-lg p-4 hover:bg-gray-50 transition-colors">
                      <Link href={`/product/${variant.slug}`}>
                        <div className="cursor-pointer">
                          <h4 className="font-semibold text-gray-900 mb-2">
                            {variant.name}
                          </h4>
                          <div className="flex flex-wrap gap-2 mb-2">
                            {variant.flavor && (
                              <Badge variant="outline" className="text-xs">
                                {variant.flavor}
                              </Badge>
                            )}
                            {variant.quantity && (
                              <Badge variant="outline" className="text-xs">
                                {variant.quantity}
                              </Badge>
                            )}
                          </div>
                          <p className="text-sm text-gray-600 line-clamp-2 overflow-hidden">
                            {variant.description && variant.description.length > 90 
                              ? `${variant.description.substring(0, 87)}...` 
                              : variant.description || "Descrizione del prodotto non disponibile"}
                          </p>
                        </div>
                      </Link>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {groupedProducts?.length === 0 && (
          <div className="text-center py-12">
            <h3 className="text-xl font-semibold text-gray-600 mb-2">
              Nessun prodotto raggruppato trovato
            </h3>
            <p className="text-gray-500">
              Non ci sono prodotti con varianti multiple in questa categoria.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/Products.tsx.content:
import { useState } from "react";
import { Link } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { productCategories } from "@/lib/constants";
import SearchBar from "@/components/SearchBar";
import { OptimizedImage } from "@/components/ui/OptimizedImage";
import { FavoriteButton } from "@/components/FavoriteButton";
import { getProductImagePath } from "@/lib/imageUtils";

// Componente per la scheda prodotto (copiato da ProductCategory.tsx)
const ProductCard = ({
  product,
}: {
  product: any;
}) => {
  // Gestisce sia prodotti dal database che prodotti statici
  const getProductImage = () => {
    // Se il prodotto ha immagini nella struttura corretta (prodotti statici)
    if (product.images && product.images.length > 0 && product.images[0].src) {
      return product.images[0].src;
    }

    // Per prodotti dal database, usa primaryImage se disponibile
    if (product.primaryImage) {
      return product.primaryImage;
    }

    // Usa il sistema universale di gestione immagini per prodotti dal database
    if (product.slug) {
      return getProductImagePath(product.slug);
    }

    // Prova anche con l'ID se slug non è presente
    if (product.id) {
      return getProductImagePath(product.id.toString());
    }

    // Fallback finale
    return "/images/placeholder-product.jpg";
  };

  const getBrandName = () => {
    return product.brand_name || product.brand || "BigGimmy";
  };

  // Funzione per calcolare il prezzo minimo del prodotto - DATABASE COME UNICA FONTE
  const getMinimumPrice = (product: any) => {
    // UNICA FONTE: Prezzo minimo dal database (campo min_price_cents dalla query SQL)
    // Database come single source of truth per rispettare la direttiva pricing
    if (product.min_price_cents && product.min_price_cents > 0) {
      return product.min_price_cents / 100; // Converti da centesimi a euro
    }

    return null;
  };

  return (
    <div className="bg-white border border-gray-200 rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-all duration-300">
      <div className="relative p-4 bg-white">
        <div className="flex items-center justify-center h-64">
          <OptimizedImage
            src={getProductImage()}
            alt={product.name}
            className="w-full h-full bg-white rounded-md"
            placeholder="/images/placeholder-product.jpg"
            width={300}
            height={256}
            objectFit="contain"
            objectPosition="center center"
          />
        </div>
        {product.isBestSeller && (
          <div className="absolute top-6 left-6 bg-red-600 text-white px-2 py-1 rounded-md text-xs font-bold uppercase z-10">
            Best Seller
          </div>
        )}
        {product.isNew && (
          <div className="absolute top-6 right-6 bg-blue-600 text-white px-2 py-1 rounded-md text-xs font-bold uppercase z-10">
            Novità
          </div>
        )}
      </div>

      <div className="p-4">
        {/* Marca */}
        <div className="text-sm text-gray-500 mb-1">{getBrandName()}</div>

        {/* Nome prodotto */}
        <h3 className="font-bold text-lg mb-2 h-14 overflow-hidden">
          {product.product_group_name || product.name}
        </h3>

        {/* Descrizione */}
        <p className="text-sm text-gray-600 mb-3 line-clamp-2 overflow-hidden">
          {product.description && product.description.length > 90
            ? `${product.description.substring(0, 87)}...`
            : product.description || "Descrizione del prodotto non disponibile"}
        </p>

        {/* Prezzo */}
        <div className="mb-4">
          {(() => {
            const minPrice = getMinimumPrice(product);
            if (minPrice && minPrice > 0) {
              return (
                <div className="flex flex-col">
                  <span className="text-sm text-gray-500 mb-1">
                    A partire da
                  </span>
                  <div className="flex items-center gap-2">
                    <span className="text-2xl font-bold text-[#FFD100]">
                      €{minPrice.toFixed(2)}
                    </span>
                    {product.originalPrice && (
                      <span className="text-lg text-gray-500 line-through">
                        €{product.originalPrice}
                      </span>
                    )}
                  </div>
                </div>
              );
            } else {
              return (
                <div className="flex flex-col">
                  <span className="text-sm text-gray-500 mb-1">
                    Prezzo su richiesta
                  </span>
                  <span className="text-lg font-bold text-gray-600">
                    Contattaci
                  </span>
                </div>
              );
            }
          })()}
        </div>

        {/* Pulsante di azione */}
        <div className="flex gap-2">
          <Link
            href={`/prodotti/${product.category_slug}/${product.slug || product.id}`}
            className="flex-1 bg-[#FFD100] hover:bg-yellow-500 text-black font-bold py-2 px-4 rounded-md transition-colors duration-200 text-center"
          >
            Vedi Dettagli
          </Link>
          <FavoriteButton
            productId={product.id}
            productSlug={product.slug}
            productName={product.name}
            brandName={product.brand_name || product.brandName}
            categoryName={product.category_name || product.categoryName}
            categorySlug={product.category_slug}
            basePrice={null}
            variant="icon"
            size="md"
            className="bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 p-2 rounded-md transition-colors duration-200"
          />
        </div>
      </div>
    </div>
  );
};

const Products = () => {
  const [searchFilters, setSearchFilters] = useState({
    searchQuery: '',
    brandSlug: 'all',
    priceRange: 'all',
    sortBy: 'name',
  });

  // Carica tutti i prodotti dal database
  const {
    data: products = [],
    isLoading,
    error,
  } = useQuery({
    queryKey: ["products", "all", searchFilters],
    queryFn: async () => {
      const params = new URLSearchParams();

      if (searchFilters.searchQuery) {
        params.append('search', searchFilters.searchQuery);
      }
      if (searchFilters.brandSlug !== 'all') {
        params.append('brand', searchFilters.brandSlug);
      }
      if (searchFilters.priceRange !== 'all') {
        params.append('priceRange', searchFilters.priceRange);
      }
      if (searchFilters.sortBy !== 'name') {
        params.append('sortBy', searchFilters.sortBy);
      }

      const url = params.toString() ? `/api/products?${params}` : '/api/products';
      const response = await fetch(url);
      if (!response.ok) return [];
      return response.json();
    },
    // Usa la configurazione globale di cache per aggiornamenti prezzi immediati
  });

  const handleSearch = (filters: any) => {
    setSearchFilters(filters);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Products Hero */}
      <section className="bg-[#212121] text-white py-12 sm:py-16 md:py-20">
        <div className="container mx-auto px-4 text-center">
          <h1 className="text-3xl sm:text-4xl md:text-5xl font-montserrat font-bold mb-4 sm:mb-6">
            I Nostri <span className="text-[#FFD100]">Prodotti</span>
          </h1>
          <p className="max-w-3xl mx-auto text-base sm:text-lg px-2">
            Scopri la nostra selezione completa di integratori e accessori per il fitness di alta qualità.
          </p>
        </div>
      </section>

      {/* Products Section */}
      <section className="py-8">
        <div className="container mx-auto px-4">
          {/* Search Bar */}
          <SearchBar
            onSearch={handleSearch}
            placeholder="Cerca in tutto il catalogo..."
          />

          {/* Quick Category Links */}
          <div className="mb-8">
            <h2 className="text-xl font-bold mb-4">Cerca per categoria</h2>
            <div className="flex flex-wrap gap-2">
              {productCategories.map((category) => (
                <Link
                  key={category.slug}
                  href={`/prodotti/${category.slug}`}
                  className="bg-white hover:bg-gray-100 text-gray-700 px-4 py-2 rounded-md border border-gray-200 text-sm font-medium transition-colors duration-200"
                >
                  {category.name}
                </Link>
              ))}
            </div>
          </div>

          {/* Loading State */}
          {isLoading && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {[...Array(12)].map((_, i) => (
                <div
                  key={i}
                  className="bg-white rounded-lg shadow-md overflow-hidden animate-pulse"
                >
                  <div className="aspect-square bg-gray-200" />
                  <div className="p-4 space-y-3">
                    <div className="h-4 bg-gray-200 rounded w-3/4" />
                    <div className="h-3 bg-gray-200 rounded w-full" />
                    <div className="h-3 bg-gray-200 rounded w-2/3" />
                    <div className="h-6 bg-gray-200 rounded w-1/2" />
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Error State */}
          {error && (
            <div className="text-center py-12">
              <p className="text-red-600 mb-4">
                Si è verificato un errore nel caricamento dei prodotti.
              </p>
              <button
                onClick={() => window.location.reload()}
                className="bg-[#FFD100] hover:bg-yellow-500 text-black font-bold py-2 px-4 rounded"
              >
                Riprova
              </button>
            </div>
          )}

          {/* Products Grid */}
          {!isLoading && !error && products.length > 0 && (
            <>
              <div className="flex justify-between items-center mb-6">
                <p className="text-gray-600">
                  <span className="font-semibold">{products.length}</span> prodotti
                  {searchFilters.searchQuery && (
                    <span> per "<span className="font-semibold">{searchFilters.searchQuery}</span>"</span>
                  )}
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {products.map((product: any) => (
                  <ProductCard key={product.id} product={product} />
                ))}
              </div>
            </>
          )}

          {/* No Results */}
          {!isLoading && !error && products.length === 0 && (
            <div className="text-center py-12">
              <h3 className="text-xl font-bold text-gray-900 mb-2">
                Nessun prodotto trovato
              </h3>
              <p className="text-gray-600">
                Prova a modificare i filtri di ricerca.
              </p>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

export default Products;

